"""La red de seguridad del despliegue, que el generador vuelca con el sitio.

Esta aqui y no empotrado en armar.py porque son tres archivos enteros y no
cambian casi nunca: en armar.py serian 15 KB de literal entre el CSS y el JS
del diseno, y lo que hay que poder leer de un vistazo es el diseno.

POR QUE EXISTEN LOS TRES
Todas las rutas del sitio son relativas a proposito ('fotos/x.webp'): asi se
abre con doble clic desde una carpeta, se sube a la raiz de un dominio o se
mete en una subcarpeta sin tocar una linea. El precio es que depende de dos
cosas que pone el SERVIDOR y no los archivos: que la direccion de una carpeta
termine en barra, y que fotos/ y marca/ se hayan subido completas.

Las dos fallaron en produccion. Jorge desplego el sitio y «se perdieron todas
las fotos»: el servidor contestaba 200 al HTML y 404 a cada .webp, sin un solo
error a la vista. Medido con Chromium antes de arreglarlo:

    raiz del dominio          0 imagenes rotas
    subcarpeta con barra      0 imagenes rotas
    subcarpeta SIN barra     27 imagenes rotas, 35 peticiones a 404
    sin la carpeta fotos/    47 imagenes rotas, en silencio

El ancla de rutas NO esta aqui: va EN LINEA en el <head> de cada pagina, en
armar.py, antes del primer <link>. Tiene que ser asi — si viviera en
revision.js, revision.js seria el primero en no cargar.
"""

ARCHIVOS = {
  "revision.js": "/* ──────────────────────────────────────────────────────────────────────────\n   revision.js · la red de seguridad del despliegue\n\n   POR QUE EXISTE\n   Todas las rutas de este sitio son RELATIVAS a propósito: 'fotos/x.webp',\n   'marca/logo.webp'. Eso es lo que permite abrirlo con doble clic desde una\n   carpeta, subirlo a la raíz de un dominio o meterlo en una subcarpeta sin\n   tocar una línea. El precio de esa libertad es que depende de DOS cosas que\n   las pone el servidor, no los archivos:\n\n     1. que la dirección de la página termine en «/» cuando es una carpeta;\n     2. que las carpetas fotos/ y marca/ se hayan subido completas.\n\n   Si una de las dos falla, el navegador pide las imágenes un nivel más\n   arriba (o no las encuentra) y la página se ve entera PERO SIN FOTOS, sin\n   un solo error a la vista. Pasó en producción: se desplegó el sitio y «se\n   perdieron todas las fotos». El servidor respondía 200 al HTML y 404 a cada\n   .webp, en silencio.\n\n   Lo que hace este archivo:\n     · reintenta la foto en minúsculas una vez  (un FTP o un ZIP descuidado\n       convierte vc01A-0.webp en vc01a-0.webp y en Linux eso ya es otro\n       archivo: 404);\n     · si aun así falla, deja un hueco con una leyenda honesta en lugar de un\n       icono roto con el texto alternativo encimado;\n     · y, SOLO si fallan varias, levanta un aviso que dice qué carpeta falta y\n       qué hay que hacer. En un despliegue correcto este aviso no aparece\n       nunca, porque nunca hay un error que contar.\n\n   El ancla de las rutas NO está aquí: va EN LINEA en el <head> de cada\n   página, antes del primer <link>. Tiene que ser así — si estuviera en este\n   archivo, este archivo sería el primero en no cargar.\n   ────────────────────────────────────────────────────────────────────────── */\n(function () {\n  'use strict';\n\n  var fallos = 0, carpetas = Object.create(null), avisado = false;\n\n  // El hueco se dibuja con CSS propio y no toca estilo.css: estilo.css se\n  // regenera desde el proyecto y un cambio a mano ahí se perdería.\n  var hoja = document.createElement('style');\n  hoja.textContent =\n    'img.ty-hueco{font-size:0;color:transparent;background:#141417 ' +\n    'url(\"data:image/svg+xml;charset=utf8,%3Csvg xmlns=\\'http://www.w3.org/2000/svg\\' width=\\'220\\' height=\\'34\\'%3E%3Ctext x=\\'110\\' y=\\'22\\' text-anchor=\\'middle\\' font-family=\\'ui-monospace,monospace\\' font-size=\\'12\\' letter-spacing=\\'1.5\\' fill=\\'%235b5b66\\'%3EFOTO NO DISPONIBLE%3C/text%3E%3C/svg%3E\") ' +\n    'center/auto no-repeat;outline:1px solid #26262c;outline-offset:-1px}' +\n    '.ty-aviso{position:fixed;left:0;right:0;top:0;z-index:99999;' +\n    'background:#1d1206;border-bottom:2px solid #f2b705;color:#f6e6c4;' +\n    'font:14px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;' +\n    'padding:12px 56px 12px 16px;text-align:left}' +\n    '.ty-aviso b{color:#f2b705}' +\n    '.ty-aviso a{color:#f2b705}' +\n    '.ty-aviso button{position:absolute;right:10px;top:8px;background:none;' +\n    'border:1px solid #6b5a2a;color:#f6e6c4;font:inherit;cursor:pointer;' +\n    'padding:3px 10px;line-height:1.4}';\n  (document.head || document.documentElement).appendChild(hoja);\n\n  function carpetaDe(s) {\n    var i = s.indexOf('/');\n    return i > 0 ? s.slice(0, i) : '(raíz)';\n  }\n\n  function avisar() {\n    if (avisado) return;\n    avisado = true;\n    var cuales = Object.keys(carpetas).sort();\n    var d = document.createElement('div');\n    d.className = 'ty-aviso';\n    d.setAttribute('role', 'status');\n    d.innerHTML =\n      '<b>Faltan las imágenes de la página.</b> El servidor contesta ' +\n      '«no existe» a ' + (cuales.length === 1\n        ? 'la carpeta <b>' + cuales[0] + '/</b>'\n        : 'las carpetas <b>' + cuales.join('/</b> y <b>') + '/</b>') +\n      '. Hay que subirla completa, al lado de <b>index.html</b>, sin ' +\n      'cambiarle el nombre. Detalle y comprobación en ' +\n      '<a href=\"revisar.html\">revisar.html</a>.' +\n      '<button type=\"button\">cerrar</button>';\n    d.querySelector('button').addEventListener('click', function () { d.remove(); });\n    document.body.appendChild(d);\n  }\n\n  // Los errores de carga de <img> no burbujean: hay que escucharlos en\n  // captura sobre document, no en body con el modelo normal.\n  document.addEventListener('error', function (e) {\n    var im = e.target;\n    if (!im || im.tagName !== 'IMG') return;\n    var s = im.getAttribute('src') || '';\n    if (!s || s.slice(0, 5) === 'data:') return;\n\n    if (!im.hasAttribute('data-ty-min') && s !== s.toLowerCase()) {\n      im.setAttribute('data-ty-min', '1');\n      im.src = s.toLowerCase();\n      return;\n    }\n    if (im.classList.contains('ty-hueco')) return;\n\n    im.classList.add('ty-hueco');\n    carpetas[carpetaDe(s)] = 1;\n    if (++fallos >= 3) avisar();\n  }, true);\n})();\n",
  "revisar.html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex\">\n<title>Toydarians · revisión del despliegue</title>\n<!-- Esta pagina NO usa estilo.css ni motor.js a proposito: si el despliegue\n     esta roto, esos dos son justo los que no cargan. Tiene que poder\n     explicarse sola, con sus propios estilos dentro. -->\n<style>\n  :root{color-scheme:dark}\n  *{box-sizing:border-box}\n  body{margin:0;background:#0A0A0B;color:#e7e7ea;\n       font:15px/1.6 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;\n       padding:28px 18px 60px}\n  .caso{max-width:760px;margin:0 auto}\n  h1{font-size:19px;letter-spacing:.14em;text-transform:uppercase;margin:0 0 4px;color:#f2b705}\n  .sub{color:#8b8b95;margin:0 0 26px;font-size:13px}\n  h2{font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:#8b8b95;\n     margin:30px 0 10px;border-bottom:1px solid #26262c;padding-bottom:7px;font-weight:400}\n  .f{display:flex;gap:12px;align-items:baseline;padding:7px 0;border-bottom:1px solid #18181c}\n  .e{flex:0 0 76px;font-weight:700;letter-spacing:.08em;font-size:12px}\n  .ok .e{color:#4ec97b} .mal .e{color:#ff5c5c} .esp .e{color:#8b8b95}\n  .q{flex:1;min-width:0;word-break:break-all}\n  .q small{display:block;color:#f6c86b;font-size:13px;margin-top:3px;word-break:normal}\n  .dato{color:#8b8b95;font-size:13px;padding:4px 0}\n  .dato b{color:#e7e7ea;font-weight:400}\n  .caja{border:1px solid #26262c;background:#131317;padding:14px 16px;margin:14px 0}\n  .caja p{margin:0 0 9px} .caja p:last-child{margin:0}\n  code{background:#1d1d22;padding:1px 6px;color:#f2b705}\n  a{color:#f2b705}\n  #resumen{padding:14px 16px;margin:18px 0 0;border-left:3px solid #3a3a42;background:#131317}\n  #resumen.bien{border-left-color:#4ec97b}\n  #resumen.mal{border-left-color:#ff5c5c}\n</style>\n</head>\n<body>\n<div class=\"caso\">\n\n<h1>Revisión del despliegue</h1>\n<p class=\"sub\">Toydarians · esta página comprueba que el sitio quedó bien subido. No forma parte de la tienda; puedes borrarla cuando todo esté en verde.</p>\n\n<div id=\"resumen\">Comprobando…</div>\n\n<h2>Dónde está servida</h2>\n<div id=\"ctx\"></div>\n\n<h2>Archivos y carpetas</h2>\n<div id=\"lista\"></div>\n\n<h2>¿Y el administrador?</h2>\n<div class=\"caja\">\n  <p><b>Este sitio no tiene administrador.</b> Son archivos sueltos: tres páginas HTML, una hoja de estilo y las fotos. No hay WordPress, ni base de datos, ni panel: por eso carga rápido y no se puede hackear por el login.</p>\n  <p>Los precios, las existencias y los textos viven en los archivos <code>datos-*.js</code>, y <b>se generan desde el proyecto</b>. Si se editan a mano, el cambio se pierde la próxima vez que se regeneren: para cambiar un precio o una foto hay que pedirlo y se vuelve a generar.</p>\n  <p>La tienda vieja de WordPress (la de <code>toydarians.com</code>) sigue teniendo el suyo, en su propia dirección, y no cambia nada por haber subido este sitio: son dos cosas separadas.</p>\n  <p>Lo único que se toca a mano aquí es una línea de <code>motor.js</code>, la del Client ID de PayPal. Viene explicada paso a paso en <code>LEEME.txt</code>.</p>\n</div>\n\n</div>\n\n<script>\n(function(){\n  var lista = document.getElementById('lista'),\n      ctx   = document.getElementById('ctx'),\n      res   = document.getElementById('resumen'),\n      local = location.protocol === 'file:',\n      mal = 0, esperando = 0, hechos = 0;\n\n  // ── contexto ────────────────────────────────────────────────────────────\n  var p = location.pathname,\n      i = p.lastIndexOf('/'),\n      u = p.slice(i+1),\n      carpeta = (u === '' || u.indexOf('.') > -1) ? p.slice(0,i+1) : p + '/';\n\n  function dato(k,v){\n    var d = document.createElement('div');\n    d.className = 'dato';\n    d.innerHTML = k + ': <b></b>';\n    d.querySelector('b').textContent = v;\n    ctx.appendChild(d);\n  }\n  dato('Dirección', location.href);\n  dato('Carpeta del sitio', location.origin === 'null' ? carpeta : location.origin + carpeta);\n  dato('Servido desde', local ? 'el disco (file://) — súbelo a un hosting para la prueba de verdad' : 'un servidor web');\n\n  // ── comprobaciones ──────────────────────────────────────────────────────\n  var pruebas = [\n    ['marca/logo.webp',      'img', 'El logotipo. Si falla, la carpeta marca/ no se subió o se le cambió el nombre.'],\n    ['marca/heroe.webp',     'img', 'La foto grande de la portada. Misma carpeta marca/.'],\n    ['marca/letras/l0.webp', 'img', 'Las letras de la animación de entrada. marca/ tiene que subirse con sus subcarpetas dentro.'],\n    ['fotos/vc57-0.webp',    'img', 'Una foto de producto. Si falla, la carpeta fotos/ no llegó completa: son más de 300 archivos y una subida a medias los deja fuera.'],\n    ['fotos/vc01A-0.webp',   'img', 'Foto con MAYÚSCULA en el nombre (vc01A). Si ésta falla y las demás pasan, el servidor o el programa de subida cambió los nombres a minúsculas: en Linux eso ya es otro archivo.'],\n    ['fotos/cat/funko-2.webp','img','Una foto de categoría. fotos/ tiene una subcarpeta cat/ dentro.'],\n    ['estilo.css',           'txt', 'La hoja de estilo. Si falla, la página se ve como texto suelto sin maquetar.'],\n    ['motor.js',             'txt', 'El buscador, los filtros y el carrito. Si falla, no se puede comprar.'],\n    ['datos-vintage-collection.js','txt','El catálogo de las 47 figuras.'],\n    ['marca/bungee-latin.woff2','txt','La tipografía del logotipo.']\n  ];\n\n  function fila(ruta, estado, nota){\n    var d = document.createElement('div');\n    d.className = 'f ' + estado;\n    var e = document.createElement('span'); e.className = 'e';\n    e.textContent = estado === 'ok' ? 'BIEN' : estado === 'mal' ? 'FALLA' : '…';\n    var q = document.createElement('span'); q.className = 'q';\n    q.textContent = ruta;\n    if (nota){ var s = document.createElement('small'); s.textContent = nota; q.appendChild(s); }\n    d.appendChild(e); d.appendChild(q);\n    return d;\n  }\n\n  function cerrar(){\n    if (hechos < esperando) return;\n    res.className = mal ? 'mal' : 'bien';\n    if (!mal){\n      res.innerHTML = '<b>Todo bien.</b> Las ' + esperando + ' comprobaciones pasaron. ' +\n        'El sitio está completo y servido desde la carpeta correcta.' +\n        (local ? ' (Visto desde el disco; repite esta prueba en el hosting.)' : '');\n    } else {\n      res.innerHTML = '<b>' + mal + ' de ' + esperando + ' comprobaciones fallan.</b> ' +\n        'Debajo de cada una está qué significa. Casi siempre es lo mismo: ' +\n        'hay que volver a subir la carpeta <b>completa</b>, tal cual salió del ZIP, ' +\n        'sin mover ni renombrar nada, y dejando <b>index.html</b> al mismo nivel que ' +\n        '<b>fotos/</b> y <b>marca/</b>.';\n    }\n  }\n\n  pruebas.forEach(function(t){\n    var ruta = t[0], tipo = t[1], nota = t[2];\n    var d = fila(ruta, 'esp', '');\n    lista.appendChild(d);\n    esperando++;\n\n    function marcar(bien, extra){\n      hechos++;\n      if (!bien) mal++;\n      var n = d.cloneNode(false);\n      var nuevo = fila(ruta, bien ? 'ok' : 'mal', bien ? '' : (nota + (extra ? ' · ' + extra : '')));\n      d.replaceWith(nuevo); d = nuevo;\n      cerrar();\n    }\n\n    if (tipo === 'img'){\n      var im = new Image();\n      im.onload  = function(){ marcar(true); };\n      im.onerror = function(){ marcar(false, ''); };\n      im.src = ruta + '?r=' + Date.now();\n      return;\n    }\n\n    if (local){\n      // fetch sobre file:// lo bloquea el navegador: no es un fallo del sitio.\n      hechos++;\n      var nuevo = fila(ruta, 'esp', 'No se puede comprobar desde el disco. Súbelo a un hosting y vuelve a abrir esta página.');\n      d.replaceWith(nuevo); d = nuevo;\n      esperando--; cerrar();\n      return;\n    }\n\n    fetch(ruta + '?r=' + Date.now(), { cache: 'no-store' })\n      .then(function(r){ marcar(r.ok, r.ok ? '' : 'el servidor contestó ' + r.status); })\n      .catch(function(){ marcar(false, 'no hubo respuesta'); });\n  });\n})();\n</script>\n</body>\n</html>\n",
  ".htaccess": "# ─────────────────────────────────────────────────────────────────────────\n# Toydarians · ajustes para hosting Apache / cPanel\n#\n# Este archivo SOLO lo lee Apache (cPanel, Hostinger, GoDaddy y parecidos).\n# En Netlify, Vercel, Cloudflare Pages o GitHub Pages se ignora por completo\n# y no estorba: se puede subir siempre.\n#\n# Resuelve tres cosas que han roto despliegues reales de este sitio:\n# ─────────────────────────────────────────────────────────────────────────\n\n# 1 · LA BARRA FINAL\n#    Si alguien entra a  midominio.com/tienda  (sin la barra), el navegador\n#    resuelve 'fotos/x.webp' como midominio.com/fotos/x.webp — un nivel mas\n#    arriba — y la pagina se queda sin estilos, sin datos y sin fotos, con\n#    un 200 en el HTML y 404 en todo lo demas. Esto hace que Apache redirija\n#    a /tienda/ antes de que pase nada.\nDirectorySlash On\nDirectoryIndex index.html\n\n<IfModule mod_rewrite.c>\n  # 2 · WORDPRESS NO SE LLEVA ESTOS ARCHIVOS\n  #    Si esta carpeta cuelga de una instalacion de WordPress, el .htaccess\n  #    del directorio padre manda cualquier peticion a index.php. Apagar\n  #    mod_rewrite AQUI deja fuera esas reglas para esta carpeta y sus\n  #    subcarpetas, sin tocar nada de la tienda vieja.\n  RewriteEngine Off\n</IfModule>\n\n# 3 · LOS TIPOS DE ARCHIVO\n#    Apache antiguo no conoce .webp ni .woff2 y los entrega como binario\n#    suelto. Casi todos los navegadores lo perdonan; algunos proxies no.\n<IfModule mod_mime.c>\n  AddType image/webp  .webp\n  AddType font/woff2  .woff2\n  AddType text/javascript .js\n  AddType text/css    .css\n</IfModule>\n\n# Cache larga para las fotos (no cambian de nombre nunca) y corta para el\n# HTML, para que un cambio de precio se vea el mismo dia.\n<IfModule mod_expires.c>\n  ExpiresActive On\n  ExpiresByType image/webp \"access plus 30 days\"\n  ExpiresByType font/woff2 \"access plus 30 days\"\n  ExpiresByType text/html  \"access plus 10 minutes\"\n</IfModule>\n"
}


def escribir(raiz):
    """Vuelca los tres archivos en la carpeta del sitio. Devuelve los nombres.

    Solo escribe si el contenido CAMBIO, para que `git status` no marque tres
    archivos tocados en cada regeneracion y el diff diga la verdad. Es la
    misma regla que sigue escribir_activos() en armar.py.
    """
    puestos = []
    for nombre, texto in ARCHIVOS.items():
        ruta = raiz / nombre
        if not ruta.exists() or ruta.read_text(encoding='utf-8') != texto:
            ruta.write_text(texto, encoding='utf-8')
        puestos.append(nombre)
    return puestos
